// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceMeasurer {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceMeasurer = UniffiVTableCallbackInterfaceMeasurer(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeMeasurer.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface Measurer: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeMeasurer.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface Measurer: handle missing in uniffiClone")
            }
        },
        measureId: { (
            uniffiHandle: UInt64,
            uniffiOutReturn: UnsafeMutablePointer<UInt64>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> UInt64 in
                guard let uniffiObj = try? FfiConverterTypeMeasurer.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.measureId(
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterUInt64.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        measureIntrinsics: { (
            uniffiHandle: UInt64,
            leaves: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> [FfiIntrinsics] in
                guard let uniffiObj = try? FfiConverterTypeMeasurer.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.measureIntrinsics(
                     leaves: try FfiConverterSequenceTypeFfiLeaf.lift(leaves)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterSequenceTypeFfiIntrinsics.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        measureHeights: { (
            uniffiHandle: UInt64,
            leaves: RustBuffer,
            requests: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<RustBuffer>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> [Float] in
                guard let uniffiObj = try? FfiConverterTypeMeasurer.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.measureHeights(
                     leaves: try FfiConverterSequenceTypeFfiLeaf.lift(leaves),
                     requests: try FfiConverterSequenceTypeFfiHeightRequest.lift(requests)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterSequenceFloat.lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceMeasurer> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceMeasurer>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

private func uniffiCallbackInitMeasurer() {
    uniffi_exponential_ui_ffi_fn_init_callback_vtable_measurer(UniffiCallbackInterfaceMeasurer.vtablePtr)
}

