/**
 * A RESOLVED theme (built-in or loaded), shared by surfaces and painters.
 */
public protocol ThemeProtocol: AnyObject, Sendable {
    
    /**
     * A colour token for the mode (`foreground`, `primary`, `chart1`…), hex.
     */
    func color(name: String, mode: String)  -> String?
    
    /**
     * Every colour token of the mode as `{name: hex}` JSON.
     */
    func colorsJson(mode: String)  -> String
    
    /**
     * A control token in px (`input`, `switch`, `iconSm`…).
     */
    func control(name: String)  -> Double?
    
    /**
     * The numeric box a control's recipe fixes (`{width, height, …}`), JSON.
     */
    func controlGeometry(component: String, propsJson: String) throws  -> String
    
    /**
     * A family NAME (`sans` → `Inter`); the host registers the font.
     */
    func fontFamily(kind: String)  -> String?
    
    /**
     * `{family: {fallback, weights, source}}` JSON.
     */
    func fontsJson()  -> String
    
    func id()  -> String
    
    func lineHeight(name: String)  -> Double?
    
    func name()  -> String
    
    func opacity(name: String)  -> Double?
    
    func radius(name: String)  -> Double?
    
    /**
     * A sub-part's look: `owner_component/part` for the OWNER's props (the
     * recipe props are derived here, like the core does) and `states`.
     */
    func resolvePart(ownerComponent: String, part: String, ownerPropsJson: String, states: [String], mode: String) throws  -> FfiPartStyle
    
    /**
     * The RESOLVED theme as JSON (what `builtin_theme_json` returns).
     */
    func resolvedJson()  -> String
    
    func spacing(name: String)  -> Double?
    
    func typeSize(name: String)  -> Double?
    
}
