    typealias SwiftType = FfiImageHeader

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiImageHeader {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .unknown
        
